const monograms: Record<string, [string, string]> = {
  'BRK.B': ['B', '#7099c7'], COST: ['CO', '#e63445'], PEP: ['P', '#3583d3'], PG: ['P&G', '#559ae1'],
  DIS: ['D', '#9287e8'], JNJ: ['J&J', '#e25363'], LLY: ['L', '#ef5b64'], UNH: ['U', '#4d8fc9'],
  PFE: ['P', '#50a9e8'], XOM: ['XOM', '#e24a52'], CVX: ['C', '#428fcc'], ASML: ['ASML', '#7b82d6'],
  ALV: ['A', '#598ecf'], MC: ['LV', '#c3a569'], OR: ['L', '#c7a485'], TTE: ['TE', '#ed627c'],
  NESN: ['N', '#bd9878'], ROG: ['R', '#598bea'], NOVN: ['N', '#e79943'], NOVO_B: ['N', '#7596d2'],
  AZN: ['AZ', '#b982c1'], '9984': ['SB', '#b7c3d4'], '2330': ['TSMC', '#d46168'], '700': ['T', '#6a8bec'],
  '1211': ['BYD', '#e25b65'], '2222': ['SA', '#50b9b2'], BHP: ['BHP', '#e49056'], CBA: ['C', '#e4bb54'],
  RY: ['RBC', '#558fe1'], VALE: ['V', '#51af92'], PBR: ['BR', '#5aac6d'], MELI: ['M', '#dfc24c'],
};
const bonds = new Set(['BND', 'TLT', 'IEF', 'SHY', 'AGG', 'TIP', 'LQD']);
const dividends = new Set(['SCHD', 'VYM', 'VIG', 'DVY', 'HDV']);

function readableColor(hex: string) {
  const channels = [1, 3, 5].map(offset => parseInt(hex.slice(offset, offset + 2), 16));
  const high = Math.max(...channels), low = Math.min(...channels);
  if (high - low < 20 && high < 80) return '#dce5ef';
  const mix = high < 160 ? 0.34 : high < 210 ? 0.12 : 0;
  return '#' + channels.map(value => Math.round(value + (255 - value) * mix).toString(16).padStart(2, '0')).join('');
}

export type AssetIconProps = {
  ticker: string;
  name?: string;
  type?: string;
  className?: string;
};

/** Decorative, local SVG. Render the asset name alongside it for an accessible label. */
export function AssetIcon({ ticker, name, type, className = '' }: AssetIconProps) {
  const symbol = ticker.toUpperCase();
  const brand = brands[symbol];
  const isBond = type === 'Облигации' || bonds.has(symbol);
  const isDividend = type === 'Дивиденды' || dividends.has(symbol);
  const fundColor = symbol.startsWith('V') || symbol === 'BND' ? '#ed7785' : symbol === 'SCHD' ? '#63b5ed' : '#61c9b4';
  const fallback = monograms[symbol] || [(/^[0-9]/.test(symbol) ? name?.split(/\s+/).map(word => word[0]).join('') : symbol)?.replace(/[^\p{L}\p{N}&]/gu, '').slice(0, 3) || '•', '#899beb'];
  const color = isBond || isDividend ? fundColor : readableColor(brand?.color || fallback[1]);
  return <svg className={['asset-icon', className].filter(Boolean).join(' ')} style={{'--asset-ink':color} as CSSProperties} viewBox="0 0 40 40" width="40" height="40" aria-hidden="true" focusable="false" data-icon-kind={isBond ? 'bond' : isDividend ? 'dividend' : brand ? 'brand' : 'monogram'}>
    <rect x=".6" y=".6" width="38.8" height="38.8" rx="12" fill={color} fillOpacity=".11" stroke={color} strokeOpacity=".23" strokeWidth="1.2" />
    <path d="M12 1h16a11 11 0 0 1 11 11v7C31 7 15 4 1 19v-7A11 11 0 0 1 12 1Z" fill="#fff" opacity=".035" />
    {isBond ? <g fill="none" stroke={color} strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round">
      <path d="M13 9.5h11l4 4V30H12V11a1.5 1.5 0 0 1 1.5-1.5ZM23 10v5h5M16 19h8M16 23h5M16 27h3" />
    </g> : isDividend ? <g fill="none" stroke={color} strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
      <path d="M20 27V16M20 23c-5.5 0-9-3-9-8 5.5 0 9 3 9 8ZM20 18c0-5.5 3-8 9-8 0 5.5-3.5 8-9 8Z" />
      <ellipse cx="20" cy="29" rx="8" ry="2.8" />
    </g> : brand ? <path d={brand.path} transform="translate(8 8)" fill={color} /> : <text x="20" y="20.7" textAnchor="middle" dominantBaseline="middle" fill={color} fontFamily="Inter, Arial, sans-serif" fontSize={fallback[0].length > 3 ? 8.5 : fallback[0].length > 2 ? 10 : 14} fontWeight="750" letterSpacing={fallback[0].length > 2 ? '-.3' : '-.5'}>{fallback[0]}</text>}
  </svg>;
}

export default AssetIcon;


